    "si.about.eyebrow": "About the Institute",
    "si.about.lead": "SNA Institute, part of SNA, bridges the gap between academic research and practical application. The Institute conducts research in AI, Robotics and IoT, and provides a platform for exceptional graduates of our programmes to gain intensive, hands-on experience through our Elite Internship Programme. This internship encompasses both academic research in AI, Robotics and IoT, as well as valuable venture building experience.",
