    "si.pillar.venture.title": "Venture Building Experience",
    "ss.bisp.desc": "British International School Phuket (BISP), under the Arthit Ourairat Institution, partnered with SNA for a 2-day Tech and AI Workshop with 20+ Grade 12 students. In teams, they learned about AI, Generative AI and Robotics, developed startup ideas and pitched them to BISP's senior management.",
    "ss.bisp.loc": "Phuket, Thailand",
    "ss.bisp.p1": "AI fundamentals, Generative AI and robotics applications",
    "ss.bisp.p2": "Team-based startup ideation and innovation",
    "ss.bisp.p3": "Final pitch presentations to school management",
    "ss.bisp.p4": "Built confidence in tech entrepreneurship and public speaking",
    "ss.bisp.title": "British International School Phuket — Tech & AI Workshop",
    "ss.chula.desc": "Since January 2025, our engagement with the School of Integrated Innovation at Chulalongkorn University — Thailand's leading university — demonstrates our impactful work. We delivered two 15-week venture building programmes to 240+ first-year BAScii students. This core course covered venture creation essentials: AI coding, robotic arm construction (3D printers), idea generation, fundraising, evaluation and presentations.",
    "ss.chula.loc": "Bangkok, Thailand",
    "ss.chula.p1": "15-week core academic course delivered twice to 240+ students",
    "ss.chula.p2": "AI coding, robotics and venture creation curriculum",
