    "ss.chula.p4": "Interactive learning: Sapiens Game & SuperNova Role Play",
    "ss.chula.title": "Venture Building Programmes — BAScii Students",
    "ss.hero.eyebrow": "Our Success Stories",
    "ss.hero.lead": "A look back at the programmes, camps and hackathons we have delivered with our partners around the world since January 2025.",
    "ss.hero.title": "Programmes That Changed Lives",
    "ss.hku.loc": "Hong Kong",
    "ss.hku.p1.desc": "The HKU Summer Institute at the University of Hong Kong partnered with SNA to host a two-week NextGen Entrepreneurs Boot Camp in 2025. 100+ students from Germany, Russia, the US, the UK, Taiwan, Thailand, Singapore and China participated. In teams, they explored Generative AI and Robotics, developed startup ideas and pitched them to three female judges, supported by 15+ guest speakers including venture investors, entrepreneurs, engineers and investment bankers.",
    "ss.hku.p1.title": "NextGen Entrepreneurs Boot Camp",
    "ss.hku.p2.desc": "Our co-founder Sammi Wong, HKU's Honorary Lecturer, led two sessions at the HKU Summer Institute on \"Pitching Skills & Storytelling\" and \"Fundraising 101 & Tech Startup Sharing\" in 2026. 100+ students from China, Kazakhstan, North America, Southeast Asia, Taiwan and the UK formed teams to pitch startup concepts, receiving direct feedback from Professor Wong and two guest judges, alongside 4 guest speakers including venture investors and family office leaders.",
    "ss.hku.p2.title": "Technopreneurship: Launching Solutions through Innovation",
    "ss.hku.title": "HKU Summer Institute",
    "ss.human.camp1.desc": "SNA partnered with Pasona Group to launch the first three-day Tech Boot Camp in Awaji, Japan, for a group of students from the prestigious Osaka University. Students developed practical and innovative venture ideas using AI and sensors to improve the operational performance of Pasona Group's hospitality facilities in Awaji.",
    "ss.human.camp1.title": "Camp I — Osaka University (February 2026)",
    "ss.human.camp2.desc": "An expanded 5-day second edition welcomed elite students from Hong Kong, India and Thailand. Highlights: an elite cohort; industry focus on real-world AI, sensing and robotics in hospitality; venture creation and pitching to an international panel from 5 countries; and authentic Japanese cultural immersion.",
    "ss.human.camp2.title": "Camp II — International Cohort (July 2026)",
    "ss.human.loc": "Awaji Island, Japan",
    "ss.human.title": "Human+Tech Futures Camp I & II",
    "ss.imperial.desc": "Authorised by Imperial College London, SNA launched the inaugural Imperial Engineering Summer School for Under-18s in July 2026 — an intensive week of mechanical engineering through motorsport, hands-on lab workshops, F24 kit car racing and F1 guest speakers, in one of the world's leading universities.",
    "ss.imperial.loc": "London, United Kingdom",
