    "ss.imperial.p4": "Imperial alumni networking plus a mini hackathon",
    "ss.imperial.title": "Imperial Engineering Summer School 2026",
    "ss.ksa.loc": "Riyadh, Saudi Arabia",
    "ss.ksa.p1.desc": "Co-organised with the Munich-based W3-FF Venture Builder, SNA participated in the NextG3N Web3 Hackathon at Princess Nourah Bint Abdulrahman University in Riyadh. Over three days, it attracted 100+ participants from 16 nationalities, with women making up over 40% of attendees. The hackathon featured 8 hacking teams and 14 sponsors, with strong support from HRH Princess Nourah AlFaisal of Saudi Arabia.",
    "ss.ksa.p1.title": "NextG3N Web3 Hackathon",
    "ss.ksa.p2.desc": "In February 2026, SNA co-organised the Trust & Pay Hackathon with the Munich-based W3-FF Venture Builder at Prince Saud University in Riyadh. Over three days, nine teams from across the Middle East participated in this dynamic fintech event, including college students and working professionals. We were honoured to have Bosch, the German tech giant, as principal sponsor, alongside more than 15 supporting organisations, including the Web3 Alliance of Saudi Arabia and the Fetch.ai Foundation.",
    "ss.ksa.p2.title": "Trust & Pay Hackathon",
    "ss.ksa.title": "Tech Hackathons in Saudi Arabia",
