    "p.hero.sub": "Sapiens Nova Academy is dedicated to developing tailored, interactive insights in technology, innovation, venture investment, and entrepreneurship. We prepare young adults for future careers as venture capitalists, entrepreneurs, and technology professionals.",
    "p.hero.explore": "Explore Programmes",
    "p.fea.pill": "Featured Programmes",
    "p.fea.title": "Featured Programmes",
    "p.fea.lead": "Explore our flagship summer programmes designed for future innovators and leaders.",
    "p.custom.pill": "Customised Programmes",
    "p.custom.title": "Tailored Learning Experiences",
    "p.custom.lead": "Our customised programmes focus on innovation, entrepreneurship, and technology. From boot camps to psychology courses, we offer diverse opportunities for growth.",
    "p.service.ai.badge": "AI / Robotics",
    "p.service.ai.title": "AI / Robotics",
    "p.service.ai.desc": "The AI Robotics Programme is a fast-paced, hands-on programme designed for innovators, engineers, developers, and tech enthusiasts who want to build intelligent robotic systems in a collaborative, high-energy environment. Unlike traditional academic programmes, this bootcamp focuses on practical implementation, rapid prototyping, and real-world problem solving. Participants learn by building – working in teams to design, train, and deploy AI-powered robotic systems over an intensive short-term format.",
    "p.service.pg.badge": "Personal Growth",
    "p.service.pg.title": "Personal Growth",
    "p.service.pg.desc": "The Personal Growth Programme is a transformative course designed to help individuals gain deeper insight into their personality, strengths, motivations, and interpersonal style through structured psychometric assessment and guided reflection. At the heart of the programme is the use of the Myers-Briggs Type Indicator (MBTI), one of the world's most widely used personality frameworks. Participants explore how psychological preferences influence decision-making, communication style, stress responses, leadership approach, and personal development pathways. This course goes beyond labels. It provides practical tools for self-awareness, confidence building, emotional intelligence, and intentional growth.",
    "p.service.vc.badge": "Start-up/VC",
    "p.service.vc.title": "Start-up & Venture Capital",
    "p.service.vc.desc": "The Start-up & Venture Capital Programme is an intensive, experience-driven course designed for aspiring founders, early-stage startups, and innovation-driven professionals seeking to understand the venture capital ecosystem while actively participating in it. This programme goes beyond classroom theory. It is structured around live pitching sessions, startup competitions, and professional sharing forums with experienced founders, venture capitalists, and industry leaders. Participants gain first-hand exposure to how investment decisions are made, how startups are evaluated, and what truly differentiates fundable ventures.",
    "p.service.ws.badge": "Workshops",
    "p.service.ws.title": "Workshops",
    "p.service.ws.desc": "This dynamic workshop series is designed to provide participants with immersive, practical experiences across four interconnected domains shaping today's global landscape: ESG and sustainability leadership, Japanese culture and business philosophy, and the evolving creative industries. Each workshop emphasizes experiential learning, collaborative exercises, case discussions, and real-world application rather than passive lectures. Participants gain practical tools, cross-cultural insights, and innovation-oriented mindsets applicable to both corporate and entrepreneurial settings.",
    "p.learn": "Learn More",
    "p.track.pill": "Our Track Record",
    "p.track.title": "Proven Excellence",
    "p.track.lead": "Delivering innovative programmes that combine technology, entrepreneurship, and hands-on learning.",
    "p.tab.hku": "HKU Summer Institute Nextgen Entrepreneurs Boot Camp",
    "p.tab.chula": "Chulalongkorn Venture Building Programme",
    "p.tab.web3": "Nextg3n Web3 Hackathon - KSA",
    "p.tab.bisp": "Tech & AI Workshop - BISP",
    "p.hku.b1": "Partnered with the HKU Summer Institute at the University of Hong Kong",
    "p.hku.b2": "100+ students from Germany, Russia, the US, the UK, Taiwan, Thailand, Singapore, and China participated",
    "p.hku.b3": "In teams, they explored Generative AI and Robotics, developed startup ideas, and pitched them to three female judges",
    "p.hku.b4": "15+ guest speakers, including venture investors, entrepreneurs from various sectors, engineers from tech startups, and investment bankers",
    "p.chula.b1": "15-week venture building programme for 110 first-year students",
    "p.chula.b2": "Partner: School of Integrated Innovation, Chulalongkorn University",
    "p.chula.b3": "Core academic course: AI coding, robotics, fundraising, and pitching",
    "p.chula.b4": "Built robotic arms using 3D printers",
    "p.chula.b5": "Interactive learning: Sapiens Game & SuperNova Role Play",
    "p.chula.b6": "Delivered as official university curriculum",
    "p.web3.b1": "100+ participants from 16 nationalities in Riyadh",
    "p.web3.b2": "Co-organised with W3-FF Venture Builder (Munich)",
    "p.web3.b3": "Venue: Princess Nourah Bint Abdulrahman University",
    "p.web3.b4": "Over 40% female participation, 8 hacking teams",
    "p.web3.b5": "Support from HRH Princess Nourah AlFaisal",
    "p.web3.b6": "Established SNA presence in Saudi Arabia tech ecosystem",
    "p.bisp.b1": "2-day immersive workshop for 20+ Grade 12 students",
    "p.bisp.b2": "Partner: British International School Phuket",
    "p.bisp.b3": "AI fundamentals, Generative AI, and robotics applications",
    "p.bisp.b4": "Team-based startup ideation and innovation",
    "p.bisp.b5": "Final pitch presentations to school management",
    "p.bisp.b6": "Built confidence in tech entrepreneurship and public speaking",

