    "cta.enrol": "立即报名",
    "hero.title": "拥抱你的未来：<br>创业构建、身心健康、艺术与文化",
    "hero.sub": "我们培养年轻一代成为未来的风险投资人、企业家和技术专家——通过遍布香港、泰国、日本、中国、英国和沙特阿拉伯的变革性课程。",
    "hero.explore": "浏览课程",
