    marquee: "夏季课程报名现已开放",
    "statement.eyebrow": "关于我们",
    "statement.title": "以创新赋能未来领袖",
    "statement.lead": "Sapiens Nova Academy 是一所充满活力的教育机构，致力于在科技、创新、风险投资和创业领域培养量身定制、互动式的洞察力——以变革性的教育激发每位学生的潜能。",
    "pillar.innovate.title": "创业构建",
    "pillar.innovate.desc": "我们的创业构建课程专注于创新、创业以及科技创企的创建与投资。我们在香港、泰国、日本、深圳及英国提供定制课程，结合集训营、黑客松、路演、工作坊、专业人士分享活动以及创业或风投竞赛，为学生提供全球视野与亲身实践，打造具有影响力的创企。",
    "pillar.heal.title": "身心健康",
    "pillar.heal.desc": "我们与剑桥心理学家 Rina Lai 博士合作，提供身心健康课程，培养心理福祉、领导力以及路演叙事能力。通过聚焦式工作坊，学生建立韧性并培养成长型思维，凸显身心健康与沟通对成功的重要性。",
    "pillar.inspire.title": "艺术与文化",
    "pillar.inspire.desc": "与东京证券交易所上市公司 Pasona Group Inc.（2168.T）合作，学生得以使用淡路岛的顶级设施——音乐剧场、豪华酒店、主题乐园与高级餐饮——为演出及与日本艺术家的文化交流提供理想舞台。",
    "programs.eyebrow": "我们的课程",
    "programs.title": "面向未来领袖的全面课程",
