    "stories.eyebrow": "学生心声",
    "stories.title": "学生成功故事",
    t1: "朱拉隆功大学的15周创业构建课程令我脱胎换骨。我学会了 AI 编程，组装了机械臂，还向真正的投资人路演了我的创业想法。",
    t2: "参加港大暑期学院集训营的经历难以置信。机器人实操课和风险投资家的指导，给了我别处无法获得的见解。",
    t3: "帝国理工学院的科技集训营超出了我的所有期待。与行业专家共事、在真实场景中学习 AI，让我有信心在大学攻读计算机科学。",
    t4: "Future by Design 心理学课程通过 MBTI 测评和剑桥心理专家的个人发展辅导，帮助我更了解自己。",
    t5: "参加利雅得 Nextg3n Web3 黑客松改变了我的命运。与来自16个国家的学生相遇，让我看到了科技与创新的全球机遇。",
