    /* ---------- programmes page ---------- */
    "p.hero.pill": "创新教育",
    "p.hero.title": "开启你的未来",
    "p.hero.sub": "Sapiens Nova Academy 致力于在科技、创新、风险投资与创业领域培养量身定制、互动式的洞察力。我们帮助年轻人成为未来的风险投资人、企业家和技术专家。",
    "p.hero.explore": "浏览课程",
    "p.fea.pill": "精选项目",
    "p.fea.title": "精选项目",
    "p.fea.lead": "探索专为未来创新者与领袖设计的旗舰夏季课程。",
    "p.custom.pill": "定制课程",
    "p.custom.title": "量身定制的学习体验",
    "p.custom.lead": "我们的定制课程聚焦创新、创业与科技。从集训营到心理学课程，为成长提供多元机遇。",
    "p.service.ai.badge": "AI / 机器人",
    "p.service.ai.title": "AI / 机器人",
    "p.service.ai.desc": "AI 机器人课程是一项快节奏、重实践的集训营。课程为创新者、工程师、开发者和技术爱好者而设，在协作、充满激情的环境中打造智能机器人系统。与传统学术课程不同，本课程专注于实际应用、快速原型开发和真实问题解决。学员边做边学——以高强度短期集训形式，在团队中设计、训练和部署 AI 驱动的机器人系统。",
    "p.service.pg.badge": "个人成长",
    "p.service.pg.title": "个人成长",
    "p.service.pg.desc": "个人成长课程是一门变革性课程，通过结构化的心理测评与引导式反思，帮助个人更深入地了解自己的性格、优势、动机与社交风格。课程的核心是使用迈尔斯-布里格斯类型指标（MBTI）——全球应用最广泛的性格框架之一。参与者探索心理偏好如何影响决策、沟通风格、压力应对、领导方式和个人发展路径。本课程不止于标签，它提供了自我觉察、自信建立、情商与有意识成长等实用工具。",
    "p.service.vc.badge": "创业/风投",
    "p.service.vc.title": "创业与风险投资",
    "p.service.vc.desc": "创业与风险投资课程是一门高强度、重经验的项目，面向希望了解并参与风险投资生态系统的准创业者、早期创业公司以及创新驱动的专业人士。本课程超越课堂理论，围绕真实路演、创业大赛以及与资深创业者、风险投资人和行业领袖的专业交流论坛展开。参与者将亲身了解投资决策是如何做出的、创业公司如何被评估，以及真正可投资企业的核心竞争力是什么。",
    "p.service.ws.badge": "工作坊",
    "p.service.ws.title": "工作坊",
    "p.service.ws.desc": "本系列工作坊在四个相互关联的领域（ESG 与可持续发展领导力、日本文化与商业哲学、不断发展的创意产业）为参与者带来沉浸式、重实践的体验。每个工作坊都强调经验式学习、协作练习、案例分析，以及面对现实的应用，而非被动授课。参与者将获得适用于企业职业与创业场景的实用工具、跨文化见解与创新导向的思维模式。",
    "p.learn": "了解更多",
    "p.track.pill": "我们的成就",
    "p.track.title": "卓越证明",
    "p.track.lead": "提供融合科技、创业与动手学习的创新课程。",
    "p.tab.hku": "香港大学暑期学院青年企业家集训营",
    "p.tab.chula": "朱拉隆功大学创业构建课程",
