    "pi.eyebrow": "官方课程",
    "pi.title": "帝国理工大学赛车工程暑期学校",
    "pi.desc": "本官方课程结合赛车工程基础、实践设计工作，并亲身体验帝国理工大学的学术环境。",
    "pi.chip.date": "2026 年 7 月 19 日至 25 日",
