    "pi.sess.note": "提示：这是帝国理工大学赛车工程暑期学校的联合宣讲会。在原始网站中，报名按钮可打开线上网络研讨会注册；参与者在每次会议后都会收到促销码。",
    "pi.faq.q1": "为什么要参加帝国理工大学的赛车工程课程？",
    "pi.faq.a1": "本课程为您提供在全球顶尖大学体验赛车工程实践式教育的独特机会。参与者将参与实践工作坊、设计挑战与工程参观，深入了解真实赛车应用。本课程非常适合热爱工程与赛车运动的学生，让您在顶级学术环境中向专家学习并获取宝贵技能。",
    "pi.faq.q2": "与其他暑期学校相比，本课程有何独特之处？",
    "pi.faq.a2": "本课程将帝国理工大学官方课程与完整动手工程体验巧妙结合：从搭建、测量简单模型，到设计并组装真正的 F24 套件车传动系统——全程在帝国理工学院的学术环境中并借助其工程设施完成。",
    "pi.faq.q3": "申请帝国理工大学课程有哪些要求？",
    "pi.faq.a3": "申请者须证明其英语能力满足课程要求。为评估英语水平与整体匹配度，申请者将受邀参加面试。通过者将收到录取邮件以锁定课程名额。",
    "pi.faq.q4": "课程费用包含哪些项目？",
    "pi.faq.a4": "课程费用包括课程全部材料与设备；入住帝国理工大学学生宿舍；帝国理工大学校园基础设施；校园工程参观；专业工程指导；申请者个人陈述审阅；大学申请指导；以及帝国理工大学结业证书。",
    "pi.faq.q5": "课程费用不包含哪些项目？",
    "pi.faq.a5": "课程费用不涵盖个人开销（如洗衣、话费、购物或纪念品）、往返交通、旅行与医疗保险、签证费及相关费用、课程官方日期以外的住宿，以及课程序外的自主活动项目。机场接送不包含在内。",
    "pi.faq.q6": "完成课程后能获得学术学分吗？",
    "pi.faq.a6": "不能！本课程为非学分暑期学校课程。",
    "pi.faq.q7": "参加本课程有先修要求吗？",
    "pi.faq.a7": "本课程没有特定先修要求，旨在适应背景和学会水平多样的学生。",
    "pi.faq.q8": "退款政策是怎样的？",
    "pi.faq.a8": "申请费不可退还。课程费用可能需要遵守我们的退营政策。具体的退款条款与条件，请联系我们的招生团队。",
    "pi.faq.q9": "提供怎样的住宿？",
    "pi.faq.a9": "学生入住帝国理工大学南肯辛顿校园的学生宿舍。宿舍可便捷地抵达所有课程活动与伦敦的景点设施。",
    "pi.faq.q10": "课程中包含哪些工程活动？",
    "pi.faq.a10": "课程包括搭建简单模型、进行运算、操作 1:9 比例赛车、动力总成设计挑战、组装 F24 套件车，以及学习包括阻力、下压力与压力效应在内的赛车空气动力学。",
    "pi.faq.q11": "会获得帝国理工大学的证书吗？",
    "pi.faq.a11": "是的，成功完成课程的所有参与者都将获得帝国理工大学颁发的结业证书。",
    "pi.faq.q12": "我可以使用哪些校园设施？",
    "pi.faq.a12": "参与者可使用帝国理工大学校园设施（包括工程实验室），并获得校园工程团队。",
    "pi.faq.q13": "课程费用包含餐饮吗？",
    "pi.faq.a13": "课程费用包含住宿与餐饮；有关餐饮安排与额外费用的细节，请联系我们的招生团队。",
    "pi.faq.q14": "参加课程需要带什么？",
    "pi.faq.a14": "将为入读学生提供详细的携带物品清单，包括工程工作坊所需全部用品。大部分技术设备与材料由课程提供；不过学生需自备笔记本电脑与个人物品。",
    "pi.cta.title": "准备好开始你的旅程了吗？",
    "pi.cta.sub": "加入帝国理工大学赛车工程暑期学校，体验世界级的工程教育。",

