    "ph.eyebrow": "夏令营",
    "ph.title": "人类+科技未来夏令营",
    "ph.desc": "未来创新者在这里学习打造改善生活的科技。通过 AI、感知与机器人技术的实践学习，学生将打造能应对健康与幸福领域现实挑战的原型。在专家指导下，参与者接触创新、创业与全球协作，为快速演变的未来做好准备。",
    "ph.chip.date": "2026 年 7 月 13-17 日",
    "ph.chip.age": "年龄 15-22",
    "ph.chip.lang": "英语",
    "ph.chip.loc": "日本淡路岛",
    "ph.fee.loc.label": "地点",
    "ph.fee.loc.detail": "日本兵库县淡路岛 Hotel Bourou Seikaiha",
