    "ph.high.1": "打造真正影响人类的 AI 解决方案",
    "ph.high.2": "掌握以人为中心的设计与创新思维",
    "ph.high.3": "学习创业公司如何从想法走到落地",
    "ph.high.4": "在动手工作坊中打造真实技术原型",
    "ph.high.5": "在高绩效的国际化团队中协作",
    "ph.high.6": "像创始人一样向行业专家路演",
    "ph.sec.why": "为什么要参加",
    "ph.why.1": "向世界级专家学习：由帝国理工大学资深学者与经验丰富的风险投资基金经理主讲。",
    "ph.why.2": "与行业合作解决真实挑战：与 Pasona 集团团队共同完成真实商业与创新项目。",
    "ph.why.3": "贯通科技与创业：获得在大学前课程中少见的技能与创业思维。",
    "ph.inc.1": "Hotel Bourou Seikaiha 住宿（共享双人间）",
    "ph.inc.2": "课程期间每日三餐",
    "ph.inc.3": "全部教学、工作坊与材料",
    "ph.inc.4": "日本本地交通",
    "ph.inc.5": "文化活动与实地参观（包括主题公园）",
    "ph.out.1": "在 AI、创新与以人为本的设计方面打下坚实基础",
    "ph.out.2": "打造真实技术解决方案的实践经历",
    "ph.out.3": "接触风险投资思维，了解创业公司如何被评估",
    "ph.out.4": "理解如何开发、验证并路演商业构想",
    "ph.out.5": "建立团队协作、沟通与公开发言的自信",
    "ph.out.6": "通过与 Pasona 集团合作洞察真实世界创新",
    "ph.loc.1": "日本兵库县兵荒岛 Hotel Bourou Seikaiha",
    "ph.loc.2": "五星级度假村环境，俯瞰壮阔海景",
    "ph.loc.3": "现代化会议设施与专用动手学习空间",
    "ph.loc.4": "传统日本温泉体验，放松身心",
    "ph.loc.5": "丰富的文化环境，邻近当地景点、餐饮与主题公园",
    "ph.pay.1": "需支付 3,000 港元定金以确保名额。",
    "ph.pay.2": "成功录取的申请者须在录取后支付课程全款 17,000 港元。",
    "ph.pay.3": "早鸟价——优惠截至 2026 年 4 月 29 日（15,000 港元）。",
    "ph.admission": "申请本课程须填写申请表。为评估申请者的整体匹配度，申请者可能会被邀请参加面试。通过者将收到录取邮件，接受后（并支付课程费用）即可锁定名额。",
    "ph.faq.q1": "为什么要参加日本的人类+科技未来夏令营？",
    "ph.faq.a1": "人类+科技未来夏令营提供独特的机会，通过真实的实践学习探索科技如何改善人类幸福。参与者将：利用 AI 与新兴技术打造并原型化科技解决方案；在团队中协作应对现实挑战；接触创业知与方法；与 Pasona 集团合作解决实践挑战；在淡路岛激励人心的环境中体验日本文化。本课程非常适合于对科技、创新以及为世界创造有意义影响充满好奇的学生。",
    "ph.faq.q2": "本课程与其他暑期课程有什么不同？",
    "ph.faq.a2": "人类+科技未来夏令营在独特的国际化环境中，将科技、创业与真实行业经验相结合，超越了传统科技营。参与者将：与 Pasona 集团协作解决真实挑战；向包括帝国理工学者与资深风投经理在内的专家学习；亲手打造并原型科技解决方案，而非仅学理论；培养从想法到路演的创业思维；在顶级学习环境中体验日本文化并入住淡路岛。与只注重编程或课堂学习的传统课程不同，本夏令营强调以人为本的创新、真实应用与全球化视野。",
    "ph.faq.q3": "课程费用包含哪些项目？",
    "ph.faq.a3": "课程费用涵盖夏令营体验的全部核心内容，包括：Hotel Bourou Seikaiha 住宿（共享双人间）；课程期间每日三餐；全部教学、工作坊与学习材料；作为课程行程一部分的日本本地交通；文化活动与实地参观，包括当地景点与主题公园。",
    "ph.faq.q4": "课程费用不包含哪些项目？",
    "ph.faq.a4": "往返日本机票；旅行与医疗保险；签证费用及相关成本（如适用）；个人开销（例如购物、零食、纪念品）；课程行程以外的自主或替换旅行安排；以及课程计划之外的自选活动。",
    "ph.faq.q5": "课程包含哪些文化活动？",
    "ph.faq.a5": "传统温泉体验，放松身心；参观岛上当地景点与主题公园；通过与当地专业人士（包括 Pasona 集团的团队）互动接触日本的创新文化。",
    "ph.faq.q6": "参加本课程有先修要求吗？",
    "ph.faq.a6": "没有正式的先修要求；只需对科技/创新/创业有真正的兴趣、好奇心并愿意协作。无需编程经验。",
    "ph.faq.q7": "这是一门以技术为核心的课程吗？",
    "ph.faq.a7": "不是——本课程将科技与 AI 同真实应用结合；以幸福为中心的以人为本创新；创业与商业思维；团队协作。",
    "ph.faq.q8": "提供怎样的住宿与设施？",
    "ph.faq.a8": "Hotel Bourou Seikaiha——一家五星级度假村，拥有全景海景、现代化会议设施、专门的动手学习空间以及传统日式温泉。",
    "ph.faq.q9": "参加需要科技或 AI 经验吗？",
    "ph.faq.a9": "不需要，本课程专为初学者设计；只需要对科技与创新的真正兴趣。",
    "ph.cta.title": "准备好开始你的旅程了吗？",
    "ph.cta.sub": "加入淡路岛的「人类+科技未来夏令营」，打造改善生活的科技。",

