    "up.imperial.badge": "夏令營 · 英國",
    "up.imperial.desc": "面向18歲以下學生、在倫敦帝國理工學院舉辦的一週密集型工程夏令營——以賽車運動切入機械工程、動手實驗室工作坊、F24 套件賽車，以及與帝國理工校友和招生主任交流。",
    "up.imperial.loc": "倫敦帝國理工學院，英國 · 2027年7月12–16日",
    "up.imperial.title": "Imperial Engineering Summer School 2027",
    "up.lead": "鎖定我們下一期旗艦課程的名額——報名現已開放。",
    "up.leaflet": "下載宣傳單張",
    "up.sz.badge": "從構想到簡報的創新營",
    "up.sz.desc": "坐落於中國矽谷核心地帶的快節奏創新營——從點子構思到投資者簡報一應俱全。包括參觀領先科技公司，以及與中國初創生態系統的親身創業建設實踐。",
