    "hero.title": "擁抱你的未來：<br>創業構建、身心健康、藝術與文化",
    "hero.sub": "我們培育年輕一代成為未來的風險投資人、企業家與科技專業人士——透過橫跨香港、泰國、日本、中國、英國與沙烏地阿拉伯的變革性課程。",
    "hero.explore": "瀏覽課程",
    "hero.scroll": "向下捲動探索",
    "hero.dots": "選擇投影片",
    marquee: "夏季課程現已開放報名",
    "statement.eyebrow": "關於我們",
    "statement.title": "以創新賦能未來領袖",
    "statement.lead": "Sapiens Nova Academy 是一所充滿活力的教育機構，致力於在科技、創新、風險投資與創業領域培養量身定制、互動式的洞察力——以變革性教育激發每位學生的潛能。",
    "pillar.innovate.title": "創業構建",
    "pillar.innovate.desc": "我們的創業構建課程專注於創新、創業以及科技新創公司的創建與投資。我們在香港、泰國、日本、深圳及英國提供定制課程，結合集訓營、黑客松、路演、工作坊、專業人士分享活動以及創業或創投競賽，為學生提供全球視野與親身實踐，打造具有影響力的新創公司。",
    "pillar.heal.title": "身心健康",
    "pillar.heal.desc": "我們與劍橋心理學家 Rina Lai 博士合作，提供身心健康課程，培養心理福祉、領導力以及簡報敘事能力。透過聚焦式工作坊，學生建立韌性並培養成長型思維，凸顯身心健康與溝通對成功的重要性。",
    "pillar.inspire.title": "藝術與文化",
    "pillar.inspire.desc": "與東京證券交易所上市公司 Pasona Group Inc.（2168.T）合作，學生得以使用淡路島的頂級設施——音樂劇場、豪華酒店、主題樂園與高級餐飲——為演出及與日本藝術家的文化交流提供理想舞台。",
    "programs.eyebrow": "我們的課程",
    "programs.title": "面向未來領袖的全方位課程",
    "programs.lead": "為年輕一代在科技、創業與風險投資領域的未來職涯做好準備——並在整個旅程中融入身心健康、藝術與文化。",
    "pcard.venture.title": "創業構建與創新",
    "pcard.venture.desc": "沉浸式國際創業體驗——在世界領先的創新中心舉辦集訓營、黑客松與創新工作坊。",
    "pcard.venture.loc": "香港 · 日本 · 泰國 · 沙烏地阿拉伯 · 英國",
    "pcard.wellbeing.title": "身心健康",
    "pcard.wellbeing.desc": "以研究為依託的心理學與實用工具，幫助建立情緒韌性、明確目標與可持續的成功習慣。",
    "pcard.wellbeing.loc": "香港",
    "pcard.art.title": "藝術與文化",
    "pcard.art.desc": "在日本淡路島的世界級劇院中，體驗音樂表演、專業輔導與日本動畫工作坊。",
    "pcard.art.loc": "日本淡路島",
    "pcard.sna.title": "SNA 學院",
    "pcard.sna.desc": "為科技、創新與創業構建領域有抱負的年輕人才，提供系統化導師制與定制研發項目。",
    "pcard.sna.loc": "香港",
    "pcard.more": "了解更多",
