    "stories.eyebrow": "學生心聲",
    "stories.title": "學生成功故事",
    t1: "朱拉隆功大學為期15週的創業構建課程令我脫胎換骨。我學會了 AI 程式設計，組裝了機械臂，還向真正的投資人路演了我的創業想法。",
    t2: "參加港大暑期學院集訓營的經歷令人難以置信。機器人實作課與風險投資家的指導，給了我別處無法獲得的見解。",
    t3: "帝國理工學院的科技集訓營超出了我的所有期待。與業界專家共事、在真實場景中學習 AI，讓我更有信心在大學攻讀計算機科學。",
    t4: "Future by Design 心理學課程透過 MBTI 測評與劍橋心理專家的個人發展輔導，幫助我更了解自己。",
    t5: "參加利雅德 Nextg3n Web3 黑客松改變了我的命運。與來自16個國家的學生相遇，讓我看到了科技與創新的全球機遇。",
