    /* ---------- programmes page ---------- */
    "p.hero.pill": "創新教育",
    "p.hero.title": "開啟你的未來",
    "p.hero.sub": "Sapiens Nova Academy 致力於在科技、創新、風險投資與創業領域培養量身定制、互動式的洞察力。我們幫助年輕人成為未來的風險投資人、企業家與技術專家。",
    "p.hero.explore": "瀏覽課程",
    "p.fea.pill": "精選項目",
    "p.fea.title": "精選項目",
    "p.fea.lead": "探索專為未來創新者與領袖設計的旗艦夏季課程。",
    "p.custom.pill": "定制課程",
    "p.custom.title": "量身定制的學習體驗",
    "p.custom.lead": "我們的定制課程聚焦創新、創業與科技。從集訓營到心理學課程，為成長提供多元機遇。",
    "p.service.ai.badge": "AI / 機器人",
    "p.service.ai.title": "AI / 機器人",
    "p.service.ai.desc": "AI 機器人課程是一項快節奏、重實踐的集訓。課程為創新者、工程師、開發者與科技愛好者而設，在協作、充滿活力的環境中打造智能機器人系統。與傳統學術課程不同，本課程專注於實際應用、快速原型開發與真實問題解決。學員邊做邊學——以高強度短期集訓形式，在團隊中設計、訓練並部署 AI 驅動的機器人系統。",
    "p.service.pg.badge": "個人成長",
    "p.service.pg.title": "個人成長",
    "p.service.pg.desc": "個人成長課程是一門變革性課程，透過結構化的心理測評與引導式反思，幫助個人更深入地了解自己的性格、優勢、動機與人際風格。課程的核心是使用邁爾斯-布里格斯類型指標（MBTI）——全球應用最廣泛的性格框架之一。參與者探索心理偏好如何影響決策、溝通風格、壓力反應、領導方式與個人發展路徑。本課程不止於標籤，它提供了自我覺察、建立自信、情商與有意識成長等實用工具。",
    "p.service.vc.badge": "創業/創投",
    "p.service.vc.title": "創業與風險投資",
    "p.service.vc.desc": "創業與風險投資課程是一門高強度、重體驗的項目，面向希望理解並參與風險投資生態系統的準創辦人、早期新創與創新驅動的專業人士。課程超越課堂理論，圍繞真實路演、創業競賽與分享交流展開，與資深創辦人、創投家和業界領袖對談。參與者可親身了解投資決策如何做出、新創如何被評估，以及可投資創業的真實核心競爭力。",
    "p.service.ws.badge": "工作坊",
    "p.service.ws.title": "工作坊",
    "p.service.ws.desc": "本系列工作坊在四個相互關聯領域（ESG 與永續領導力、日本文化與商業哲學、不斷演變的創意產業）為參與者帶來沉浸式、重實踐的體驗。每個工作坊都強調「做中學」、協作練習、案例討論與真實應用，而非被動授課。參與者將獲得適用於職涯與創業場景的實用工具、跨文化洞察與以創新為導向的心態。",
    "p.learn": "了解更多",
    "p.track.pill": "我們的成績",
    "p.track.title": "卓越證明",
    "p.track.lead": "提供融合科技、創業與動手學習的創新課程。",
    "p.tab.hku": "香港大學暑期學院青年創業家集訓營",
    "p.tab.chula": "朱拉隆功大學創業構建課程",
