    "pi.eyebrow": "官方課程",
    "pi.title": "帝國理工大學賽車工程暑期學校",
    "pi.desc": "本官方課程結合賽車工程基礎、實踐設計工作，並親身體驗帝國理工大學的學術環境。",
    "pi.chip.date": "2026 年 7 月 19 日至 25 日",
    "pi.chip.age": "年齡 15-17",
    "pi.chip.lang": "英語",
    "pi.chip.loc": "英國倫敦",
