    "si.about.eyebrow": "เกี่ยวกับสถาบัน",
    "si.about.lead": "สถาบัน SNA เป็นส่วนหนึ่งของ SNA เชื่อมช่องว่างระหว่างงานวิจัยเชิงวิชาการกับการประยุกต์ใช้จริง สถาบันดำเนินงานวิจัยด้าน AI หุ่นยนต์ และ IoT และเป็นเวทีให้ศิษย์เก่าที่โดดเด่นของหลักสูตรเราได้ประสบการณ์เชิงปฏิบัติอย่างเข้มข้นผ่านโครงการฝึกงาน Elite Internship Programme ซึ่งครอบคลุมทั้งงานวิจัยเชิงวิชาการด้าน AI หุ่นยนต์ และ IoT รวมถึงประสบการณ์การสร้างธุรกิจอันมีค่า",
    "si.about.title": "งานวิจัย ประสบการณ์จริง การสร้างธุรกิจ",
