    "si.cta.sub": "ศิษย์เก่าที่โดดเด่นของหลักสูตรเราสามารถสมัครโครงการฝึกงาน Elite Internship Programme และทำงานเคียงข้างเมนเทอร์ประจำสถาบัน",
