    "si.mentors.alliance.desc": "ความร่วมมือที่แข็งแกร่งกับองค์กรวิชาชีพระหว่างประเทศ รวมถึง IEEE, CFA Institute และ Royal Society of Arts เป็นต้น",
    "si.mentors.alliance.role": "เครือข่ายระดับโลก",
    "si.mentors.alliance.title": "พันธมิตรกับองค์กรวิชาชีพ",
    "si.mentors.execs.desc": "เราได้รับการสนับสนุนจากผู้บริหารระดับสูงจากหลากหลายอุตสาหกรรม รวมถึงเวนเจอร์แคปิตอล ไพรเวทอิควิตี้ การแพทย์และวิทยาศาสตร์ชีวภาพ ปัญญาประดิษฐ์และหุ่นยนต์",
    "si.mentors.execs.role": "ผู้นำอุตสาหกรรม",
    "si.mentors.execs.title": "ผู้บริหารระดับสูงมากประสบการณ์",
    "si.mentors.eyebrow": "เมนเทอร์ประจำสถาบัน",
    "si.mentors.lead": "SNA ภูมิใจที่มีกลุ่มนักวิชาการชื่อดังและผู้บริหารมากประสบการณ์เป็นเมนเทอร์ประจำสถาบัน ผู้เชี่ยวชาญเหล่านี้แบ่งปันความรู้และข้อมูลเชิงลึกเพื่อให้คำแนะนำอันมีค่าแก่ผู้เข้าร่วม และช่วยให้เข้าใจศาสตร์ของตนอย่างลึกซึ้งยิ่งขึ้น",
