    "hero.title": "โอบกอดอนาคตของคุณ:<br>การสร้างธุรกิจ สุขภาพดี ศิลปะและวัฒนธรรม",
    "hero.sub": "เราเตรียมความพร้อมให้คนรุ่นใหม่สำหรับอาชีพในอนาคตในฐานะนักลงทุนร่วมทุน ผู้ประกอบการ และผู้เชี่ยวชาญด้านเทคโนโลยี ผ่านหลักสูตรที่สร้างการเปลี่ยนแปลงในฮ่องกง ไทย ญี่ปุ่น จีน สหราชอาณาจักร และซาอุดีอาระเบีย",
    "hero.explore": "ดูหลักสูตรทั้งหมด",
    "hero.scroll": "เลื่อนลงเพื่อสำรวจ",
    "hero.dots": "เลือกสไลด์",
    marquee: "เปิดรับสมัครหลักสูตรภาคฤดูร้อนแล้ว",
    "statement.eyebrow": "เกี่ยวกับเรา",
    "statement.title": "เสริมพลังผู้นำแห่งอนาคตผ่านนวัตกรรม",
    "statement.lead": "Sapiens Nova Academy เป็นสถาบันการศึกษาที่มีชีวิตชีวา พัฒนาความเข้าใจเชิงลึกที่ออกแบบเฉพาะบุคคลและเป็นการเรียนรู้แบบมีปฏิสัมพันธ์ในด้านเทคโนโลยี นวัตกรรม การลงทุนร่วมทุน และการเป็นผู้ประกอบการ — การศึกษาที่สร้างการเปลี่ยนแปลงเพื่อปลดล็อกศักยภาพของนักเรียนทุกคน",
    "pillar.innovate.title": "การสร้างธุรกิจ",
    "pillar.innovate.desc": "โปรแกรมการสร้างธุรกิจของเรามุ่งเน้นนวัตกรรม การเป็นผู้ประกอบการ การสร้างและการลงทุนในธุรกิจเทคโนโลยี เราจัดโปรแกรมที่ปรับแต่งในฮ่องกง ไทย ญี่ปุ่น เซินเจิ้น และสหราชอาณาจักร ผสมผสานบูทแคมป์ แฮ็กกาธอน เซสชันนำเสนอ เวิร์กช็อป กิจกรรมแบ่งปันจากมืออาชีพ และการแข่งขันสตาร์ทอัพหรือ VC เพื่อมอบมุมมองระดับโลกและประสบการณ์จริงในการสร้างธุรกิจที่สร้างผลกระทบ",
    "pillar.heal.title": "สุขภาพดี",
    "pillar.heal.desc": "ร่วมกับ Dr. Rina Lai นักจิตวิทยาจากเคมบริดจ์ เราจัดโปรแกรมสุขภาวะที่ส่งเสริมสุขภาพจิตที่ดี ความเป็นผู้นำ และการเล่าเรื่องในการนำเสนอ ผ่านเวิร์กช็อปที่มุ่งเน้น นักเรียนสร้างความยืดหยุ่นและกรอบคิดแบบเติบโต โดยเน้นย้ำว่าสุขภาวะและการสื่อสารสำคัญต่อความสำเร็จ",
    "pillar.inspire.title": "ศิลปะและวัฒนธรรม",
    "pillar.inspire.desc": "ร่วมมือกับ Pasona Group Inc. (2168.T) บริษัทชั้นนำในตลาดหลักทรัพย์โตเกียว นักเรียนสามารถเข้าถึงสิ่งอำนวยความสะดวกระดับพรีเมียมของเกาะอาวาจิ—โรงละครดนตรี โรงแรมหรู สวนสนุก และการรับประทานอาหารชั้นเลิศ—เป็นเวทีที่เหมาะสำหรับการแสดงและการแลกเปลี่ยนวัฒนธรรมกับศิลปินญี่ปุ่น",
    "programs.eyebrow": "หลักสูตรของเรา",
    "programs.title": "หลักสูตรครอบคลุมสำหรับผู้นำแห่งอนาคต",
    "programs.lead": "เตรียมคนรุ่นใหม่สำหรับอาชีพด้านเทคโนโลยี การเป็นผู้ประกอบการ และการลงทุนร่วมทุน — พร้อมหลอมรวมความสุขสบาย ศิลปะ และวัฒนธรรมตลอดเส้นทางการเรียนรู้",
    "pcard.venture.title": "การสร้างธุรกิจและนวัตกรรม",
    "pcard.venture.desc": "ประสบการณ์ผู้ประกอบการระดับนานาชาติแบบเต็มรูปแบบ — ค่ายฝึกอบรม แฮ็กกาธอน และเวิร์กช็อปนวัตกรรมในศูนย์กลางนวัตกรรมชั้นนำของโลก",
    "pcard.venture.loc": "ฮ่องกง · ญี่ปุ่น · ไทย · ซาอุดีอาระเบีย · สหราชอาณาจักร",
    "pcard.wellbeing.title": "ความสุขสบาย",
    "pcard.wellbeing.desc": "จิตวิทยาที่อิงงานวิจัยและเครื่องมือปฏิบัติจริงเพื่อสร้างความเข้มแข็งทางอารมณ์ ความชัดเจนในเป้าหมาย และนิสัยแห่งความสำเร็จที่ยั่งยืน",
    "pcard.wellbeing.loc": "ฮ่องกง",
    "pcard.art.title": "ศิลปะและวัฒนธรรม",
    "pcard.art.desc": "การแสดงดนตรี การโค้ชระดับมืออาชีพ และเวิร์กช็อปแอนิเมชันญี่ปุ่น ณ โรงละครระดับโลกบนเกาะอาวาจิ ประเทศญี่ปุ่น",
    "pcard.art.loc": "เกาะอาวาจิ ญี่ปุ่น",
    "pcard.sna.title": "สถาบัน SNA",
    "pcard.sna.desc": "ระบบพี่เลี้ยงที่มีโครงสร้างชัดเจนและโครงการวิจัยและพัฒนาที่ออกแบบเฉพาะสำหรับคนเก่งรุ่นใหม่ผู้มุ่งมั่นในด้านเทคโนโลยี นวัตกรรม และการสร้างธุรกิจ",
    "pcard.sna.loc": "ฮ่องกง",
