    "life.eyebrow": "ชุมชนของเรา",
    "life.title": "ชีวิตที่ Sapiens Nova",
    "life.lead": "จากแฮ็กกาธอนในฮ่องกงและริยาด สู่ค่ายสร้างธุรกิจที่จุฬาลงกรณ์ และเวิร์กช็อปเทคโนโลยีที่ BISP — ช่วงเวลาจากหลักสูตรของเราทั่วโลก",
