    "stories.eyebrow": "เสียงจากนักเรียน",
    "stories.title": "เรื่องราวความสำเร็จของนักเรียน",
    t1: "หลักสูตรการสร้างธุรกิจ 15 สัปดาห์ที่จุฬาลงกรณ์มหาวิทยาลัยเปลี่ยนชีวิตของฉัน ฉันได้เรียนเขียนโค้ด AI สร้างแขนหุ่นยนต์ และนำเสนอไอเดียสตาร์ทอัพต่อนักลงทุนตัวจริง",
    t2: "ค่ายฝึกอบรม HKU Summer Institute ยอดเยี่ยมมาก เซสชันหุ่นยนต์แบบลงมือปฏิบัติและคำแนะนำจากนักลงทุนร่วมทุนทำให้ฉันได้มุมมองที่ไม่มีที่ไหนสอนได้",
    t3: "ค่ายเทคโนโลยีที่ Imperial College London เกินความคาดหมายทั้งหมด การทำงานร่วมกับผู้เชี่ยวชาญและเรียนรู้ AI ในสถานการณ์จริงทำให้ฉันมั่นใจจะเรียนวิทยาการคอมพิวเตอร์ในมหาวิทยาลัย",
    t4: "หลักสูตรจิตวิทยา Future by Design ช่วยให้ฉันเข้าใจตัวเองมากขึ้นผ่านแบบทดสอบ MBTI และการโค้ชพัฒนาตนเองจากนักจิตวิทยาแห่งเคมบริดจ์",
    t5: "การเข้าร่วมแฮ็กกาธอน Nextg3n Web3 ที่ริยาดเปลี่ยนชีวิตฉัน การได้พบเพื่อนนักเรียนจาก 16 ประเทศเปิดโลกทัศน์ให้เห็นโอกาสระดับโลกด้านเทคโนโลยีและนวัตกรรม",
    role1: "นักเรียน BAScii",
    role2: "นักเรียนชั้นปี 12",
    role3: "นักเรียนชั้นปี 11",
    role4: "นักเรียนชั้นปี 10",
    role5: "นักศึกษา",
    "founders.eyebrow": "รู้จักผู้ก่อตั้งของเรา",
    "founders.title": "ความเชี่ยวชาญระดับโลกนำทางเส้นทางของคุณ",
    "founders.lead": "ทีมผู้ก่อตั้งของเรารวบรวมความเชี่ยวชาญพิเศษจากสถาบันระดับโลก — งานวิจัย AI และหุ่นยนต์ที่ Imperial College London ความเป็นผู้นำด้านการลงทุนร่วมทุนที่ HKSTP Ventures และที่ปรึกษาด้านการศึกษาและจิตวิทยาจากมหาวิทยาลัยเคมบริดจ์",
