"p.hku.b1": "ร่วมเป็นพันธมิตรกับ HKU Summer Institute ณ มหาวิทยาลัยฮ่องกง",
"p.hku.b2": "นักศึกษากว่า 100 คน จากเยอรมนี รัสเซีย สหรัฐฯ สหราชอาณาจักร ไต้หวัน ไทย สิงคโปร์ และจีน เข้าร่วม",
"p.hku.b3": "ทีมสำรวจ Generative AI และหุ่นยนต์ พัฒนาไอเดียสตาร์ทอัพ และนำเสนอต่อคณะกรรมการหญิง 3 ท่าน",
"p.hku.b4": "วิทยกรรับเชิญกว่า 15 ท่าน รวมถึงผู้ลงทุนร่วม นักประกอบธุรกิจจากหลากอุตสาหกรรม วิศวกรจากสตาร์ทอัพเทคโนโลยี และธนาคารเพื่อการลงทุน",
"p.chula.b1": "หลักสูตรการสร้างธุรกิจ 15 สัปดาห์ สำหรับนักศึกษาชั้นปีที่ 1 จำนวน 110 คน",
"p.chula.b2": "พันธมิตร: คณะนวัตกรรมบูรณาการ มหาวิทยาลัยจุฬาลงกรณ์",
"p.chula.b3": "วิชาหลัก: การเขียนโค้ด AI หุ่นยนต์ การระดมทุน และการนำเสนอ",
"p.chula.b4": "สร้างแขนหุ่นยนต์ด้วยเครื่องพิมพ์ 3 มิติ",
"p.chula.b5": "การเรียนรู้แบบมีส่วนร่วม: เกม Sapiens และบทบาทสมมติ SuperNova",
"p.chula.b6": "นำเสนอเป็นหลักสูตรทางการของมหาวิทยาลัย",
