"p.web3.b6": "สร้างการปรากฏตัวของ SNA ในระบบนิเวศเทคโนโลยีของซาอุดีอาระเบีย",
"p.bisp.b1": "เวิร์กช็อปเข้มข้น 2 วัน สำหรับนักเรียนชั้น ม.6 กว่า 20 คน",
