"fd.imperial.title": "โรงเรียนฤดูร้อนวิศวกรรมมอเตอร์สปอร์ต Imperial College London",
"fd.imperial.desc": "บทนำเชิงปฏิบัติ ที่ทำให้เข้าใจว่า วิศวกรสร้าง ปรับเปลี่ยน และใช้พลังงานในบริบทของวิศวกรรมมอเตอร์สปอร์ตอย่างไร",
"fd.imperial.loc": "Imperial College London, วิทยาเขต South Kensington, ลอนดอน, สหราชอาณาจักร",
"fd.human.title": "แคมป์ฤดูร้อน Human+Tech Futures",
"fd.human.desc": "ค้นพบว่าเทคโนโลยีช่วยสนับสนุนสุขภาพที่ดีได้อย่างไร ผู้เข้าร่วมสำรวจเทคโนโลยี AI หลักและหุ่นยนต์ เพื่อสร้างต้นแบบที่ช่วยเสริมสุขภาพกายและความสมดุลทางอารมณ์",
