"pi.out.1": "เข้าใจว่าระบบกลไกส่งผ่านและแปลงกำลังอย่างไร",
"pi.out.2": "สำรวจแหล่งกำลังกลไกหลัก และวิธีที่วิศวกรวัดค่าเหล่านั้น",
"pi.out.3": "เชื่อมโยงการส่งกำลังกับสมรรถนะรถจริง และออกแบบระบบส่งกำลังที่ใช้งานได้",
"pi.out.4": "เข้าใจว่าแรงทางอากาศพลศาสตร์ถูกสร้างและนำไปใช้ในมอเตอร์สปอร์ตอย่างไร",
