    "up.imperial.badge": "Летняя школа · Великобритания",
    "up.imperial.desc": "Интенсивная недельная инженерная летняя школа для участников до 18 лет в Imperial College London — машиностроение через автоспорт, практические лабораторные воркшопы, гонки на наборах F24 и нетворкинг с выпускниками и приёмными комиссарами Imperial.",
    "up.imperial.loc": "Imperial College London, Великобритания · 12–16 июля 2027",
    "up.imperial.title": "Imperial Engineering Summer School 2027",
    "up.lead": "Забронируйте место на наших следующих флагманских программах — приём заявок открыт.",
    "up.leaflet": "Скачать буклет",
    "up.sz.badge": "Инновационный лагерь: от идеи до питча",
    "up.sz.desc": "Стремительный инновационный лагерь в самом сердце китайской Кремниевой долины — от генерации идей до питчей инвесторам. Включает визиты в ведущие технологические компании и практическое венчурное строительство в экосистеме стартапов Китая.",
    "up.sz.loc": "Шэньчжэнь, Китай",
