    "cta.enrol": "Записаться",
    "hero.title": "Примите своё будущее:<br>Построение бизнеса, благополучие, искусство и культура",
    "hero.sub": "Мы готовим молодых людей к карьере венчурных инвесторов, предпринимателей и IT-специалистов — через трансформационные программы в Гонконге, Таиланде, Японии, Китае, Великобритании и Саудовской Аравии.",
    "hero.explore": "Смотреть программы",
    "hero.scroll": "Прокрутите вниз",
    "hero.dots": "Выбрать слайд",
    marquee: "Идёт набор на летние программы",
    "statement.eyebrow": "О нас",
    "statement.title": "Раскрываем потенциал будущих лидеров через инновации",
    "statement.lead": "Sapiens Nova Academy — динамичное образовательное учреждение, развивающее у студентов индивидуальные, интерактивные навыки в сфере технологий, инноваций, венчурных инвестиций и предпринимательства — трансформационное образование, раскрывающее потенциал каждого студента.",
    "pillar.innovate.title": "Построение бизнеса",
    "pillar.innovate.desc": "Наши программы построения бизнеса фокусируются на инновациях, предпринимательстве, создании и инвестировании технологических стартапов. Мы проводим индивидуальные программы в Гонконге, Таиланде, Японии, Шэньчжэне и Великобритании, сочетая буткемпы, хакатоны, питч-сессии, воркшопы, профессиональные встречи и стартап- или VC-конкурсы, чтобы дать глобальный опыт и практические навыки для создания значимых проектов.",
    "pillar.heal.title": "Благополучие",
    "pillar.heal.desc": "В партнёрстве с доктором Риной Лай, психологом из Кембриджа, мы проводим программы благополучия, развивающие ментальное здоровье, лидерство и сторителлинг в питчах. Через сфокусированные воркшопы студенты обретают устойчивость и мышление роста, подчёркивая важность благополучия и коммуникации для успеха.",
    "pillar.inspire.title": "Искусство и культура",
    "pillar.inspire.desc": "В партнёрстве с Pasona Group Inc. (2168.T), ведущей компанией Токийской фондовой биржи, студенты получают доступ к лучшим площадкам острова Авадзи — музыкальному театру, отелям класса люкс, тематическим паркам и ресторанам высокой кухни, — предоставляя идеальную сцену для выступлений и культурного обмена с японскими художниками.",
    "programs.eyebrow": "Наши программы",
    "programs.title": "Комплексные программы для будущих лидеров",
    "programs.lead": "Мы готовим молодых людей к карьере в технологиях, предпринимательстве и венчурных инвестициях — с благополучием, искусством и культурой на протяжении всего пути.",
    "pcard.venture.title": "Венчурное строительство и инновации",
    "pcard.venture.desc": "Погружение в международное предпринимательство — буткемпы, хакатоны и инновационные мастерские в ведущих инновационных центрах мира.",
    "pcard.venture.loc": "Гонконг · Япония · Таиланд · Саудовская Аравия · Великобритания",
    "pcard.wellbeing.title": "Благополучие",
    "pcard.wellbeing.desc": "Научно обоснованная психология и практические инструменты для эмоциональной устойчивости, ясной цели и устойчивых привычек успеха.",
    "pcard.wellbeing.loc": "Гонконг",
    "pcard.art.title": "Искусство и культура",
    "pcard.art.desc": "Музыкальное исполнительство, профессиональный коучинг и мастер-классы по японской анимации в театре мирового уровня на острове Авадзи, Япония.",
    "pcard.art.loc": "Остров Авадзи, Япония",
    "pcard.sna.title": "Институт SNA",
    "pcard.sna.desc": "Структурированное наставничество и индивидуальные программы исследований и разработок для амбициозных молодых талантов в технологиях, инновациях и венчурном строительстве.",
    "pcard.sna.loc": "Гонконг",
    "pcard.more": "Узнать больше",
