    "life.eyebrow": "Наше сообщество",
    "life.title": "Жизнь в Sapiens Nova",
    "life.lead": "От хакатонов в Гонконге и Эр-Рияде до венчурных лагерей в Чулалонгкорне и технологических мастерских в BISP — моменты наших программ по всему миру.",
    photo1: "Web3-хакатон — Эр-Рияд",
