    "stories.eyebrow": "Голоса студентов",
    "stories.title": "Истории успеха студентов",
    t1: "Программа венчурного строительства в Чулалонгкорнском университете стала для меня преображением. Я научился кодить на ИИ, собрал роботизированную руку и представил свою стартап-идею настоящим инвесторам.",
    t2: "Летний буткемп HKU Summer Institute был невероятным. Практические занятия по робототехнике и наставничество венчурных инвесторов дали мне знания, которые нельзя получить нигде больше.",
    t3: "Технологический буткемп в Имперском колледже Лондона превзошёл все ожидания. Работа с экспертами отрасли и изучение ИИ на реальных примерах дали мне уверенность поступать на computer science в университет.",
    t4: "Программа по психологии Future by Design помогла мне лучше понять себя благодаря оценке MBTI и коучингу по личностному развитию под руководством кембриджского психолога.",
    t5: "Участие в хакатоне Nextg3n Web3 в Эр-Рияде изменило мою жизнь. Знакомство со студентами из 16 стран открыло мне глаза на глобальные возможности в технологиях и инновациях.",
    role1: "Студент BAScii",
    role2: "Ученик 12 класса",
