    "founders.title": "Экспертиза мирового уровня на вашем пути",
    "founders.lead": "Команда основателей объединяет выдающуюся экспертизу престижных мировых институтов — исследования ИИ и робототехники в Имперском колледже Лондона, лидерство в венчурных инвестициях в HKSTP Ventures и советника по образованию и психологии из Кембриджского университета.",
