    chat: "Открыть чат",
"p.hero.pill": "Образование, меняющее будущее",
"p.hero.title": "Раскройте свой потенциал",
"p.hero.sub": "Sapiens Nova Academy развивает персонализированное глубокое понимание технологий, инноваций, венчурного инвестирования и предпринимательства. Мы готовим молодое поколение к карьере будущего в роли венчурных инвесторов, предпринимателей и технологических экспертов",
"p.hero.explore": "Все программы",
"p.fea.pill": "Флагманские программы",
"p.fea.title": "Флагманские программы",
"p.fea.lead": "Исследуйте наши флагманские летние программы, созданные для будущих новаторов и лидеров",
"p.custom.pill": "Специализированные программы",
"p.custom.title": "Персонализированный опыт обучения",
"p.custom.lead": "Наши специализированные программы охватывают инновации, предпринимательство и технологии — от интенсивов до психологических курсов. Мы предлагаем разнообразные возможности для роста",
"p.service.ai.badge": "AI / Робототехника",
"p.service.ai.title": "AI / Робототехника",
"p.service.ai.desc": "Курс AI Robotics — это интенсивный практико-ориентированный интенсив для новаторов, инженеров, разработчиков и энтузиастов технологий, которые хотят создавать интеллектуальные робототехнические системы в динамичной командной среде. В отличие от традиционных академических курсов, этот интенсив делает акцент на практическое применение, быстрое прототипирование и решение реальных задач. Учащиеся учатся через действие, работают в командах над проектированием, обучением и внедрением робототехнических систем на базе ИИ в сжатые сроки",
"p.service.pg.badge": "Личностный рост",
"p.service.pg.title": "Личностный рост",
"p.service.pg.desc": "Курс личностного роста — это трансформационная программа, которая помогает глубоко понять свою личность, сильные стороны, мотивацию и межличностные паттерны через структурированную психологическую оценку и направленную саморефлексию. В центре программы — тест Myers-Briggs (MBTI), одна из самых популярных в мире рамок личности. Участники исследуют, как психологические проосхождения влияют на принятие решений, стиль общения, реакцию на стресс, подход к лидерству и траекторию развития. Программа выходит за рамки простых ярлыков и даёт практические инструменты для самопознания, уверенности, эмоционального интеллекта и целенаправленного роста",
"p.service.vc.badge": "Стартапы / Венчуры",
"p.service.vc.title": "Стартапы и венчурные инвестиции",
"p.service.vc.desc": "Курс Startup & Venture Capital — это интенсив, основанный на практическом опыте, созданный для будущих основателей, начинающих стартапов и профессионалов, которые хотят понять экосистему венчурного инвестирования и принять в ней участие. Курс выходит за рамки аудиторной теории: он построен вокруг живых питч-сессий, стартап-соревнований и профессиональных обсуждений с опытными основателями, венчурными инвесторами и лидерами индустрии. Участникивидят собственными глазами, как принимаются инвестиционные решения, как оцениваются стартапы и что действительно отличает финансово успешный бизнес",
"p.service.ws.badge": "Воркшопы",
"p.service.ws.title": "Воркшопы",
"p.service.ws.desc": "Эта серия динамичных воркшопов создана для глубокого практического погружения в четыре взаимосвязанные области, формирующие облик современного мира: целостность ESG и устойчивое развитие, японская деловая культура и философия, а также развивающаяся креативная индустрия. Каждый воркшоп делает акцент на практическое обучение, совместные упражнения, разбор кейсов и реальное применение, а не на пасивное прослушивание лекций. Участники получают практические инструменты, межкултural perspective и инновационное мышление, применимое как в корпорациях, так и в предпринимательстве",
"p.learn": "Подробнее",
"p.track.pill": "Наши достижения",
"p.track.title": "Подтверждаемое превосходство",
"p.track.lead": "Мы проводим инновационные программы, сочетающие технологии, предпринимательство и практическое обучение",
"p.tab.hku": "Предпринимательский интенсив HKU Summer Institute",
"p.tab.chula": "Курс Venture Building университета Чулалонгкорн",
