"p.hku.b2": "Более 100 участников из Германии, России, США, Великобритании, Тайваня, Таиланда, Сингапура и Китая",
"p.hku.b3": "Команды изучали Generative AI и робототехнику, развивали стартап-идеи и презентовали их жюри из трёх женщин",
"p.hku.b4": "Свыше 15 приглашённых спикеров, включая венчурных инвесторов, предпринимателей из разных отраслей, инженеров из технологических стартапов и инвестиционных банков",
"p.chula.b1": "15-недельная программа создания бизнеса для 110 первокурсников",
